import { readFile, writeFile } from 'node:fs/promises';
import { extname, join } from 'node:path';
import { MARKER_EXTENSIONS } from '../constants/index.js';
import { listFiles } from '../utils/fs.js';

// `// feature:a,b`, `// feature:a:start`, `{/* feature:a:end */}`, at line end.
const MARKER = new RegExp(
  [
    '\\s*(?:',
    '\\/\\/\\s*feature:([^\\r\\n]*?)',
    '|',
    '\\{\\/\\*\\s*feature:([^\\r\\n]*?)\\s*\\*\\/\\}',
    ')\\s*$',
  ].join(''),
);

const TOKEN = /^[a-z0-9][a-z0-9-]*(?:,[a-z0-9][a-z0-9-]*)*(?::(?:start|end))?$/;

type MarkerKind = 'line' | 'start' | 'end';

interface Marker {
  ids: string[];
  kind: MarkerKind;
  /** Where the marker starts, including the whitespace in front of it. */
  at: number;
}

export interface MarkerResult {
  editedFiles: string[];
  removedLines: number;
}

export class MarkerError extends Error {
  constructor(file: string, line: number, problem: string) {
    super(`${file}:${line} ${problem}`);
    this.name = 'MarkerError';
  }
}

function parseMarker(
  line: string,
  file: string,
  number: number,
  known: Set<string>,
): Marker | undefined {
  const match = MARKER.exec(line);
  if (match === null) return undefined;

  const token = (match[1] ?? match[2]).trim();
  if (!TOKEN.test(token)) {
    throw new MarkerError(file, number, `has a malformed feature marker: ${token}`);
  }

  const [list, suffix] = token.split(':');
  const ids = list.split(',');
  for (const id of ids) {
    if (!known.has(id)) {
      throw new MarkerError(
        file,
        number,
        `marks feature "${id}", which the manifest does not list`,
      );
    }
  }

  const kind: MarkerKind = suffix === 'start' || suffix === 'end' ? suffix : 'line';
  if (kind !== 'line' && line.slice(0, match.index).trim().length > 0) {
    throw new MarkerError(file, number, `puts a ${kind} marker on a line that also carries code`);
  }

  return { ids, kind, at: match.index };
}

interface Frame {
  ids: string[];
  keep: boolean;
  opened: number;
}

/**
 * Deletes the lines and blocks marked for features that were not selected, and
 * takes the marker comments off the lines that stay.
 *
 * @throws MarkerError on an unknown feature id, a malformed marker, or a block
 * that is never closed
 */
export function stripFeatureMarkers(
  content: string,
  file: string,
  kept: Set<string>,
  known: Set<string>,
): { content: string; removedLines: number } {
  const lines = content.split('\n');
  const output: string[] = [];
  const stack: Frame[] = [];
  let droppedBlocks = 0;

  lines.forEach((line, index) => {
    const number = index + 1;
    const marker = parseMarker(line, file, number, known);
    const dropping = droppedBlocks > 0;

    if (marker === undefined) {
      if (!dropping) output.push(line);
      return;
    }

    if (marker.kind === 'start') {
      const keep = marker.ids.some((id) => kept.has(id));
      stack.push({ ids: marker.ids, keep, opened: number });
      if (!keep) droppedBlocks += 1;
      return;
    }

    if (marker.kind === 'end') {
      const frame = stack.pop();
      if (frame === undefined)
        throw new MarkerError(file, number, 'closes a block that never opened');
      if (!frame.keep) droppedBlocks -= 1;
      if (frame.ids.join(',') !== marker.ids.join(',')) {
        throw new MarkerError(
          file,
          number,
          `closes ${marker.ids.join(',')} while ${frame.ids.join(',')} is open from line ${frame.opened}`,
        );
      }
      return;
    }

    if (dropping) return;
    if (!marker.ids.some((id) => kept.has(id))) return;

    const stripped = line.slice(0, marker.at);
    if (stripped.trim().length > 0) output.push(stripped + (line.endsWith('\r') ? '\r' : ''));
  });

  const unclosed = stack[stack.length - 1];
  if (unclosed !== undefined) {
    throw new MarkerError(
      file,
      unclosed.opened,
      `opens ${unclosed.ids.join(',')} and never closes it`,
    );
  }

  return { content: output.join('\n'), removedLines: lines.length - output.length };
}

/**
 * Applies stripFeatureMarkers to every source file under `root`. Files with no
 * marker are left untouched, so the result differs from the template only where
 * a marker sat.
 */
export async function removeFeatureLines(
  root: string,
  selected: string[],
  known: string[],
): Promise<MarkerResult> {
  const kept = new Set(selected);
  const ids = new Set(known);
  const editedFiles: string[] = [];
  let removedLines = 0;

  const files = (await listFiles(root)).filter((file) =>
    (MARKER_EXTENSIONS as readonly string[]).includes(extname(file)),
  );

  for (const file of files) {
    const path = join(root, file);
    const content = await readFile(path, 'utf8');
    if (!content.includes('feature:')) continue;

    const result = stripFeatureMarkers(content, file, kept, ids);
    if (result.content === content) continue;

    editedFiles.push(file);
    removedLines += result.removedLines;
    await writeFile(path, result.content, 'utf8');
  }

  return { editedFiles, removedLines };
}
import type { Manifest, PruneResult } from '../types.js';
import { removeDocLinks } from './docs.js';
import { type EnvRemovals, stripEnvFiles, writeFeatureFlag } from './env.js';
import { deleteMatchingFiles } from './files.js';
import { removeFeatureLines } from './markers.js';
import { findDanglingReferences } from './references.js';

/** Env vars only the removed features use, mapped to the words naming them. */
function removedEnvVars(manifest: Manifest, selected: Set<string>): EnvRemovals {
  const keptVars = new Set<string>();
  for (const id of selected) {
    for (const name of manifest.features[id]?.envVars ?? []) keptVars.add(name);
  }

  const removals: EnvRemovals = new Map();
  for (const [id, feature] of Object.entries(manifest.features)) {
    if (selected.has(id)) continue;
    for (const name of feature.envVars) {
      if (keptVars.has(name)) continue;
      removals.set(name, [feature.label, id]);
    }
  }
  return removals;
}

/**
 * Removes everything the unselected features own, marked lines included, then
 * reports imports that still point at deleted files.
 */
export async function prune(
  root: string,
  manifest: Manifest,
  selectedIds: string[],
): Promise<PruneResult> {
  const selected = new Set(selectedIds);
  const removed = Object.keys(manifest.features).filter((id) => !selected.has(id));

  const doomedFiles: string[] = [];
  const doomedDocs: string[] = [];
  for (const id of removed) {
    const feature = manifest.features[id];
    doomedFiles.push(...feature.files);
    doomedDocs.push(...feature.docs);
  }

  const deletedFiles = await deleteMatchingFiles(root, [
    ...manifest.core.alwaysRemoveFiles,
    ...doomedFiles,
    ...doomedDocs,
  ]);

  // Runs for every selection, not only a partial one: the full project has to
  // come out without marker comments too.
  const markers = await removeFeatureLines(root, selectedIds, Object.keys(manifest.features));

  const docs = await removeDocLinks(root, doomedDocs);
  const strippedEnvVars = await stripEnvFiles(root, removedEnvVars(manifest, selected));
  await writeFeatureFlag(root, selectedIds);
  const dangling = await findDanglingReferences(root, deletedFiles);

  return {
    selected: selectedIds,
    removed,
    deletedFiles,
    strippedEnvVars,
    removedDocLines: docs.removedLines,
    markedFiles: markers.editedFiles,
    removedMarkedLines: markers.removedLines,
    dangling,
  };
}
import { listFiles, removeFile } from '../utils/fs.js';
import { matchesAnyGlob } from '../utils/glob.js';

/**
 * Deletes every file under `root` matching one of `globs` and cleans up the
 * directories that become empty. Returns the deleted paths.
 */
export async function deleteMatchingFiles(root: string, globs: string[]): Promise<string[]> {
  if (globs.length === 0) return [];

  const files = await listFiles(root);
  const doomed = files.filter((file) => matchesAnyGlob(file, globs));

  for (const file of doomed) {
    await removeFile(root, file);
  }
  return doomed;
}
import { readFile } from 'node:fs/promises';
import { extname, join, posix } from 'node:path';
import { FRONTEND_ALIAS, FRONTEND_SOURCE, SOURCE_EXTENSIONS } from '../constants/index.js';
import type { DanglingReference } from '../types.js';
import { listFiles } from '../utils/fs.js';

// from '...' | import('...') | require('...')
const SPECIFIER = new RegExp(
  ['(?:from|import|require)', '\\s*\\(?\\s*', '[\'"]', '([^\'"]+)', '[\'"]'].join(''),
  'g',
);

function isSourceFile(path: string): boolean {
  return (SOURCE_EXTENSIONS as readonly string[]).includes(extname(path));
}

/** Strips .ts and friends. Leaves other dots alone, as in google-oauth.strategy. */
function withoutExtension(path: string): string {
  const extension = extname(path);
  const isSource = (SOURCE_EXTENSIONS as readonly string[]).includes(extension);
  return isSource ? path.slice(0, -extension.length) : path;
}

/** First path segment of a file, which is the workspace it belongs to. */
function workspaceOf(importer: string): string {
  return importer.split('/')[0];
}

/**
 * Turns an import into a project path. Relative specifiers resolve against the
 * importer; `@/x` is the frontend alias for frontend/src/x, and `src/x` is the
 * baseUrl form inside a workspace. Anything else is a package name.
 */
function resolveSpecifier(importer: string, specifier: string): string | undefined {
  if (specifier.startsWith('.')) {
    return withoutExtension(posix.normalize(posix.join(posix.dirname(importer), specifier)));
  }
  if (specifier.startsWith(FRONTEND_ALIAS)) {
    return withoutExtension(posix.join(FRONTEND_SOURCE, specifier.slice(FRONTEND_ALIAS.length)));
  }
  if (specifier.startsWith('src/')) {
    return withoutExtension(posix.join(workspaceOf(importer), specifier));
  }
  return undefined;
}

/**
 * Reports imports that point at files the pruner deleted. A non-empty result
 * means the manifest claims a file belongs to one feature while shared code
 * still depends on it.
 */
export async function findDanglingReferences(
  root: string,
  deletedFiles: string[],
): Promise<DanglingReference[]> {
  const deletedSources = deletedFiles.filter(isSourceFile).map(withoutExtension);
  if (deletedSources.length === 0) return [];

  const byPath = new Map(deletedSources.map((path) => [path, path]));
  for (const path of deletedSources) {
    // An index file is imported through its directory.
    if (path.endsWith('/index')) byPath.set(path.slice(0, -'/index'.length), path);
  }
  const dangling: DanglingReference[] = [];

  for (const file of (await listFiles(root)).filter(isSourceFile)) {
    const lines = (await readFile(join(root, file), 'utf8')).split('\n');

    lines.forEach((line, index) => {
      for (const match of line.matchAll(SPECIFIER)) {
        const specifier = match[1];
        const resolved = resolveSpecifier(file, specifier);
        const target = resolved === undefined ? undefined : byPath.get(resolved);
        if (target === undefined) continue;
        dangling.push({ file, line: index + 1, specifier, target });
      }
    });
  }

  return dangling;
}
import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import {
  CLI_NAME,
  ENV_EXAMPLE_FILES,
  FEATURE_FLAG_VAR,
  MANIFEST_FILE,
} from '../constants/index.js';

const ASSIGNMENT = new RegExp('^\\s*#?\\s*([A-Za-z_][A-Za-z0-9_]*)\\s*=');
const COMMENT = new RegExp('^\\s*#');

/** Env var name mapped to the words that identify its feature in a comment. */
export type EnvRemovals = Map<string, string[]>;

export interface EnvStripResult {
  content: string;
  stripped: string[];
}

function readKey(line: string): string | undefined {
  const match = ASSIGNMENT.exec(line);
  return match?.[1];
}

function namesFeature(comment: string, words: string[]): boolean {
  const lowered = comment.toLowerCase();
  return words.some((word) => word.length > 0 && lowered.includes(word.toLowerCase()));
}

function collapseBlankRuns(lines: string[]): string[] {
  const output: string[] = [];
  for (const line of lines) {
    const isBlank = line.trim().length === 0;
    const previousBlank = output.length > 0 && output[output.length - 1].trim().length === 0;
    if (isBlank && (previousBlank || output.length === 0)) continue;
    output.push(line);
  }
  while (output.length > 0 && output[output.length - 1].trim().length === 0) output.pop();
  return output;
}

/**
 * Drops every line assigning one of the removed vars, commented out or not,
 * along with the comment directly above it when that comment names the feature.
 */
export function stripEnvVars(content: string, removals: EnvRemovals): EnvStripResult {
  const stripped: string[] = [];
  const kept: string[] = [];

  for (const line of content.split('\n')) {
    const key = readKey(line);
    const words = key === undefined ? undefined : removals.get(key);
    if (key === undefined || words === undefined) {
      kept.push(line);
      continue;
    }

    stripped.push(key);
    const previous = kept[kept.length - 1];
    if (previous !== undefined && COMMENT.test(previous) && readKey(previous) === undefined) {
      if (namesFeature(previous, words)) kept.pop();
    }
  }

  return { content: `${collapseBlankRuns(kept).join('\n')}\n`, stripped };
}

/** Applies stripEnvVars to the generated env examples that exist. */
export async function stripEnvFiles(root: string, removals: EnvRemovals): Promise<string[]> {
  const stripped = new Set<string>();

  for (const relative of ENV_EXAMPLE_FILES) {
    const path = join(root, relative);
    let content: string;
    try {
      content = await readFile(path, 'utf8');
    } catch {
      continue;
    }
    const result = stripEnvVars(content, removals);
    if (result.stripped.length === 0) continue;
    await writeFile(path, result.content, 'utf8');
    for (const key of result.stripped) stripped.add(key);
  }

  return [...stripped].sort();
}

/** Records the enabled feature ids in the generated backend env example. */
export async function writeFeatureFlag(root: string, selected: string[]): Promise<void> {
  const path = join(root, 'backend/.env.example');
  let content: string;
  try {
    content = await readFile(path, 'utf8');
  } catch {
    return;
  }

  const block = [
    '',
    '# Authentication methods enabled in this project.',
    `# Written by ${CLI_NAME} from ${MANIFEST_FILE}.`,
    `${FEATURE_FLAG_VAR}=${selected.join(',')}`,
    '',
  ].join('\n');

  const withoutOld = content
    .split('\n')
    .filter((line) => !line.startsWith(`${FEATURE_FLAG_VAR}=`))
    .join('\n')
    .replace(/\n+$/, '\n');

  await writeFile(path, `${withoutOld}${block}`, 'utf8');
}
import { readFile, writeFile } from 'node:fs/promises';
import { basename, join } from 'node:path';
import { listFiles } from '../utils/fs.js';

const LIST_OR_ROW = new RegExp('^\\s*([-*+]|\\|)');
const LINK = '](';

export interface DocPruneResult {
  removedLines: number;
  editedFiles: string[];
}

function linksToRemovedDoc(line: string, names: string[]): boolean {
  if (!line.includes(LINK)) return false;
  return names.some((name) => line.includes(name));
}

/**
 * Drops list items and table rows that link to a doc which no longer exists.
 * Prose mentions are left alone; they need a human edit, not a line delete.
 */
export async function removeDocLinks(root: string, docPaths: string[]): Promise<DocPruneResult> {
  if (docPaths.length === 0) return { removedLines: 0, editedFiles: [] };

  const names = docPaths.map((path) => basename(path));
  const markdown = (await listFiles(root)).filter((file) => file.endsWith('.md'));
  const editedFiles: string[] = [];
  let removedLines = 0;

  for (const file of markdown) {
    const path = join(root, file);
    const lines = (await readFile(path, 'utf8')).split('\n');
    const kept = lines.filter(
      (line) => !(LIST_OR_ROW.test(line) && linksToRemovedDoc(line, names)),
    );
    if (kept.length === lines.length) continue;

    removedLines += lines.length - kept.length;
    editedFiles.push(file);
    await writeFile(path, kept.join('\n'), 'utf8');
  }

  return { removedLines, editedFiles };
}

#!/usr/bin/env node
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { CommanderError } from 'commander';
import { main } from './cli.js';
import { packageRoot } from './paths.js';

async function readVersion(): Promise<string> {
  try {
    const raw = await readFile(join(packageRoot(), 'package.json'), 'utf8');
    const parsed: unknown = JSON.parse(raw);
    const version = (parsed as { version?: unknown }).version;
    return typeof version === 'string' ? version : '0.0.0';
  } catch {
    return '0.0.0';
  }
}

try {
  process.exitCode = await main(process.argv.slice(2), await readVersion());
} catch (error) {
  if (error instanceof CommanderError) {
    process.exitCode = error.exitCode;
  } else {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}
import { readdir } from 'node:fs/promises';
import { basename, relative, resolve } from 'node:path';
import { cancel, intro, log, note, outro, spinner } from '@clack/prompts';
import { CLI_NAME } from './constants/index.js';
import { parseCliOptions } from './flags/options.js';
import { loadManifest } from './manifest/load.js';
import { defaultFeatureIds, resolveSelection } from './manifest/select.js';
import { packageRoot, templateDir } from './paths.js';
import { prune } from './prune/index.js';
import { askDirectory, askFeatures, CANCELLED } from './prompts/index.js';
import { describeDangling, describeSelection } from './report.js';
import { copyTemplate } from './scaffold/copy.js';
import { initRepository } from './scaffold/git.js';
import { detectPackageManager, installDependencies, isSupported } from './scaffold/install.js';
import { buildDocLinks, buildNextSteps } from './scaffold/next-steps.js';
import { setProjectName } from './scaffold/package-json.js';
import type { CliOptions, Manifest } from './types.js';
import { validateProjectName } from './utils/project-name.js';

const DEFAULT_DIRECTORY = 'my-app';

class CliError extends Error {}

async function isEmptyDirectory(path: string): Promise<boolean> {
  try {
    return (await readdir(path)).length === 0;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return true;
    throw error;
  }
}

/** `cd` target for the next steps: relative when that is not a stack of `..`. */
function shortestPath(target: string): string {
  const fromHere = relative(process.cwd(), target);
  if (fromHere === '') return '.';
  return fromHere.startsWith('..') ? target : fromHere;
}

async function resolveTarget(options: CliOptions): Promise<string> {
  let input = options.directory;

  if (input === undefined) {
    if (options.yes) {
      input = DEFAULT_DIRECTORY;
    } else {
      const answer = await askDirectory(DEFAULT_DIRECTORY);
      if (answer === CANCELLED) throw new CliError('Cancelled.');
      input = answer;
    }
  }

  const target = resolve(process.cwd(), input);
  const check = validateProjectName(basename(target));
  if (!check.valid) throw new CliError(check.message ?? 'Invalid project name.');
  if (!(await isEmptyDirectory(target))) throw new CliError(`${target} exists and is not empty.`);
  return target;
}

async function resolveFeatures(manifest: Manifest, options: CliOptions): Promise<string[]> {
  if (options.features !== undefined) return options.features;
  if (options.yes) return defaultFeatureIds(manifest);

  const answer = await askFeatures(manifest, defaultFeatureIds(manifest));
  if (answer === CANCELLED) throw new CliError('Cancelled.');
  return answer;
}

function requireInteractive(options: CliOptions): void {
  const needsPrompt = options.directory === undefined || options.features === undefined;
  if (!needsPrompt || options.yes || process.stdin.isTTY === true) return;
  throw new CliError('No terminal to prompt in. Pass a directory with --yes or --features.');
}

async function scaffold(target: string, manifest: Manifest, options: CliOptions): Promise<number> {
  const selection = resolveSelection(manifest, await resolveFeatures(manifest, options));
  if (selection.rejected.length > 0) {
    log.warn(`Not available yet, skipped: ${selection.rejected.join(', ')}`);
  }
  if (selection.selected.length === 0) throw new CliError('Select at least one sign-in method.');
  if (selection.added.length > 0) {
    log.info(`Added because another method needs it: ${selection.added.join(', ')}`);
  }

  const copying = spinner();
  copying.start('Copying the template');
  await copyTemplate(templateDir(), target);
  await setProjectName(target, basename(target));
  copying.stop('Template copied');

  const pruning = spinner();
  pruning.start('Removing what you did not pick');
  const result = await prune(target, manifest, selection.selected);
  pruning.stop('Pruned');
  log.message(describeSelection(manifest, result).join('\n'));

  if (result.dangling.length > 0) {
    log.error(describeDangling(result.dangling).join('\n'));
    outro(`Left the tree at ${target} so you can inspect it.`);
    return 1;
  }

  await finishSetup(target, manifest, selection.selected, options);
  return 0;
}

async function finishSetup(
  target: string,
  manifest: Manifest,
  selected: string[],
  options: CliOptions,
): Promise<void> {
  if (options.git) {
    const git = await initRepository(target);
    if (git.ok) log.step('Created a git repository with a first commit');
    else log.warn(`Skipped git: ${git.reason ?? 'git is not available'}`);
  }

  const manager = detectPackageManager();
  if (options.install && !isSupported(manager)) {
    log.warn(`${manager} is not supported yet, using npm.`);
  }

  let installed = false;
  if (options.install) {
    const installing = spinner();
    installing.start('Installing dependencies with npm');
    const install = await installDependencies(target);
    installed = install.ok;
    if (install.ok) {
      installing.stop('Dependencies installed');
    } else {
      installing.stop('npm install failed');
      log.error(install.reason ?? 'Run npm install in the project directory.');
    }
  }

  const directoryLabel = shortestPath(target);
  note(buildNextSteps({ directoryLabel, installed }).join('\n'), 'Next steps');
  note(buildDocLinks(manifest, selected).join('\n'), 'Docs');
}

export async function main(argv: string[], version: string): Promise<number> {
  const options = parseCliOptions(argv, version);
  intro(`${CLI_NAME} ${version}`);

  try {
    requireInteractive(options);
    const manifest = await loadManifest(packageRoot());
    const target = await resolveTarget(options);
    const code = await scaffold(target, manifest, options);
    if (code === 0) outro('Done.');
    return code;
  } catch (error) {
    if (error instanceof CliError) {
      cancel(error.message);
      return 1;
    }
    throw error;
  }
}
/** `hidden` features are never offered; another feature pulls them in. */
export type FeatureKind =
