import { cp, readdir, rename } from 'node:fs/promises';
import { join } from 'node:path';
import { RESTORED_FILENAMES, SKIPPED_DIRS } from '../constants/index.js';

async function restoreNames(directory: string): Promise<void> {
  const entries = await readdir(directory, { withFileTypes: true });

  for (const entry of entries) {
    const path = join(directory, entry.name);
    if (entry.isDirectory()) {
      if (SKIPPED_DIRS.has(entry.name)) continue;
      await restoreNames(path);
      continue;
    }
    const restored = RESTORED_FILENAMES[entry.name];
    if (restored !== undefined) await rename(path, join(directory, restored));
  }
}

/**
 * Copies the bundled template into the target directory and restores the file
 * names npm refuses to publish (.gitignore, package-lock.json, .npmrc).
 */
export async function copyTemplate(templateDir: string, target: string): Promise<void> {
  await cp(templateDir, target, { recursive: true });
  await restoreNames(target);
}
import {
  DEFAULT_COMMIT_MESSAGE,
  GIT_FALLBACK_EMAIL,
  GIT_FALLBACK_NAME,
} from '../constants/index.js';
import { lastLines, run } from '../utils/exec.js';

export interface GitResult {
  ok: boolean;
  reason?: string;
}

async function hasIdentity(root: string): Promise<boolean> {
  const name = await run('git', ['config', '--get', 'user.name'], root);
  const email = await run('git', ['config', '--get', 'user.email'], root);
  return name.code === 0 && email.code === 0;
}

/**
 * Creates the repository and the first commit. Runs before npm install so the
 * project's husky hooks are not installed yet and cannot reject this commit.
 */
export async function initRepository(root: string): Promise<GitResult> {
  const init = await run('git', ['init'], root);
  if (init.code !== 0) return { ok: false, reason: lastLines(init.stderr, 2) || 'git init failed' };

  const add = await run('git', ['add', '-A'], root);
  if (add.code !== 0) return { ok: false, reason: lastLines(add.stderr, 2) };

  const identity = (await hasIdentity(root))
    ? []
    : ['-c', `user.name=${GIT_FALLBACK_NAME}`, '-c', `user.email=${GIT_FALLBACK_EMAIL}`];

  const commit = await run('git', [...identity, 'commit', '-m', DEFAULT_COMMIT_MESSAGE], root);
  if (commit.code !== 0) return { ok: false, reason: lastLines(commit.stderr, 2) };

  return { ok: true };
}
import { lastLines, run } from '../utils/exec.js';

export interface InstallResult {
  ok: boolean;
  reason?: string;
}

export type PackageManager = 'npm' | 'yarn' | 'pnpm' | 'bun';

const SUPPORTED: PackageManager[] = ['npm'];

/** Reads the package manager that launched the CLI. Defaults to npm. */
export function detectPackageManager(
  userAgent = process.env.npm_config_user_agent,
): PackageManager {
  const name = userAgent?.split('/')[0];
  const known: PackageManager[] = ['npm', 'yarn', 'pnpm', 'bun'];
  return known.find((candidate) => candidate === name) ?? 'npm';
}

export function isSupported(manager: PackageManager): boolean {
  return SUPPORTED.includes(manager);
}

export async function installDependencies(root: string): Promise<InstallResult> {
  const result = await run('npm', ['install'], root);
  if (result.code === 0) return { ok: true };
  return { ok: false, reason: lastLines(result.stderr || result.stdout, 5) };
}
import type { Manifest } from '../types.js';

export interface NextStepsInput {
  directoryLabel: string;
  installed: boolean;
}

/** The commands printed after a successful scaffold. */
export function buildNextSteps(input: NextStepsInput): string[] {
  const steps = [`cd ${input.directoryLabel}`];
  if (!input.installed) steps.push('npm install');
  steps.push(
    'cp backend/.env.example backend/.env',
    'cp .env.docker.example .env.docker',
    'docker compose up -d',
  );
  return steps;
}

/** Docs worth reading for the features that were kept. */
export function buildDocLinks(manifest: Manifest, selected: string[]): string[] {
  const links = ['README.md', 'docs/README.md'];
  for (const id of selected) {
    links.push(...(manifest.features[id]?.docs ?? []));
  }
  return [...new Set(links)];
}
import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { toPackageName } from '../utils/project-name.js';

/** Names the generated project and removes commands for the maintainer browser harness. */
export async function setProjectName(root: string, projectName: string): Promise<string> {
  const path = join(root, 'package.json');
  const parsed: unknown = JSON.parse(await readFile(path, 'utf8'));
  if (typeof parsed !== 'object' || parsed === null) return projectName;

  const packageName = toPackageName(projectName);
  const updated = { ...(parsed as Record<string, unknown>), name: packageName };
  await writeFile(path, `${JSON.stringify(updated, null, 2)}\n`, 'utf8');
  const frontendPath = join(root, 'frontend', 'package.json');
  const frontend = JSON.parse(await readFile(frontendPath, 'utf8')) as {
    scripts?: Record<string, string>;
  };
  for (const command of ['test:e2e', 'test:e2e:ui', 'test:e2e:headed', 'test:e2e:debug']) {
    if (frontend.scripts) delete frontend.scripts[command];
  }
  await writeFile(frontendPath, `${JSON.stringify(frontend, null, 2)}\n`, 'utf8');
  return packageName;
}
