name: CI

on:
  push:
    branches:
      - master
  pull_request:
    branches:
      - master

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  quality:
    name: quality
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Reject prohibited tracked filenames
        run: env -i PATH="$PATH" node scripts/verify-docker.mjs --check-checkout

      - name: Prepare isolated tool home
        run: mkdir -p "$RUNNER_TEMP/ci-home"

      - name: Set up Node.js 22
        uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm

      - name: Install dependencies
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true npm ci

      - name: Lint
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true OAUTH_STATE_SECRET=synthetic-ci-state-000000000000000000 MONGO_URI=mongodb://127.0.0.1:27017/unused npm run lint

      - name: Typecheck
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true OAUTH_STATE_SECRET=synthetic-ci-state-000000000000000000 MONGO_URI=mongodb://127.0.0.1:27017/unused npm run typecheck

      - name: Build
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true OAUTH_STATE_SECRET=synthetic-ci-state-000000000000000000 MONGO_URI=mongodb://127.0.0.1:27017/unused npm run build

      - name: Test
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true OAUTH_STATE_SECRET=synthetic-ci-state-000000000000000000 MONGO_URI=mongodb://127.0.0.1:27017/unused npm run test

  scaffold-combinations:
    name: scaffold-combinations
    runs-on: ubuntu-latest
    # The workflow ships inside every generated project, where packages/ does
    # not exist. Only the boilerplate repository has a CLI to exercise.
    if: github.repository == 'Mohammed-Abdelhady/nextjs-nestjs-oauth-rbac-boilerplate'
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Reject prohibited tracked filenames
        run: env -i PATH="$PATH" node scripts/verify-docker.mjs --check-checkout

      - name: Prepare isolated tool home
        run: mkdir -p "$RUNNER_TEMP/ci-home"

      - name: Set up Node.js 22
        uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm

      - name: Install dependencies
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true npm ci

      - name: Scaffold each feature combination and typecheck it
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true npm run test:combinations -w packages/create-nest-next-auth

  backend-e2e:
    name: backend and browser integration
    runs-on: ubuntu-latest
    timeout-minutes: 35
    # Generated selections do not carry the maintainer fixture contract.
    if: github.repository == 'Mohammed-Abdelhady/nextjs-nestjs-oauth-rbac-boilerplate'
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Reject prohibited tracked filenames
        run: env -i PATH="$PATH" node scripts/verify-docker.mjs --check-checkout

      - name: Prepare isolated tool home
        run: mkdir -p "$RUNNER_TEMP/ci-home" "$RUNNER_TEMP/integration-results"

      - name: Set up Node.js 22
        uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm

      - name: Install dependencies
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true npm ci

      - name: Run fixture-backed backend integration
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true npm run test:e2e -w backend -- --runInBand

      - name: Build frontend for the synthetic API
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true NEXT_PUBLIC_API_URL=http://127.0.0.1:5107 npm run build -w frontend

      - name: Install the workspace's Chromium revision
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true npm exec --workspace frontend --no -- playwright install --with-deps chromium

      - name: Run anonymous browsers
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true PLAYWRIGHT_JSON_OUTPUT_NAME="$RUNNER_TEMP/integration-results/anonymous.json" npm run test:e2e -w frontend -- --config=playwright.frontend.config.ts --reporter=line,json

      - name: Run authenticated browsers
        run: env -i PATH="$PATH" HOME="$RUNNER_TEMP/ci-home" CI=true PLAYWRIGHT_JSON_OUTPUT_NAME="$RUNNER_TEMP/integration-results/authenticated.json" npm run test:e2e -w frontend -- --reporter=line,json

      - name: Summarize browser counts
        if: always()
        env:
          RESULTS: ${{ runner.temp }}/integration-results
        run: |
          env -i PATH="$PATH" RESULTS="$RESULTS" node --input-type=module <<'NODE'
          import { existsSync, readFileSync, writeFileSync } from 'node:fs';
          import { join } from 'node:path';
          const summary = {};
          for (const name of ['anonymous', 'authenticated']) {
            const path = join(process.env.RESULTS, `${name}.json`);
            if (!existsSync(path)) { summary[name] = { status: 'not completed' }; continue; }
            const { stats } = JSON.parse(readFileSync(path, 'utf8'));
            summary[name] = {
              executed: stats.expected + stats.unexpected + stats.flaky,
              passed: stats.expected, failed: stats.unexpected,
              skipped: stats.skipped, flaky: stats.flaky,
            };
          }
          console.log(JSON.stringify(summary, null, 2));
          if (existsSync(process.env.RESULTS)) {
            writeFileSync(join(process.env.RESULTS, 'counts.json'), JSON.stringify(summary, null, 2));
          }
          NODE

      - name: Retain synthetic count diagnostics
        if: always()
        uses: actions/upload-artifact@v4
        with:
          name: integration-counts
          path: ${{ runner.temp }}/integration-results/counts.json
          retention-days: 3
          if-no-files-found: ignore

  docker:
    name: docker
    runs-on: ubuntu-latest
    timeout-minutes: 35
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Reject prohibited tracked filenames
        run: env -i PATH="$PATH" node scripts/verify-docker.mjs --check-checkout

      - name: Set up Node.js 22
        uses: actions/setup-node@v4
        with:
          node-version: 22

      - name: Export permitted Docker source
        run: env -i PATH="$PATH" node scripts/verify-docker.mjs --export "$RUNNER_TEMP/docker-source"

      - name: Set up Docker Buildx
        uses: docker/setup-buildx-action@v3

      - name: Build backend image
        uses: docker/build-push-action@v6
        with:
          context: ${{ runner.temp }}/docker-source
          file: ${{ runner.temp }}/docker-source/backend/Dockerfile
          target: production
          push: false
          load: true
          tags: authboiler-smoke-backend:local
          cache-from: type=gha
          cache-to: type=gha,mode=max

      - name: Build frontend image
        uses: docker/build-push-action@v6
        with:
          context: ${{ runner.temp }}/docker-source
          file: ${{ runner.temp }}/docker-source/frontend/Dockerfile
          target: production
          build-args: |
            NEXT_PUBLIC_API_URL=http://127.0.0.1:5107
          push: false
          load: true
          tags: authboiler-smoke-frontend:local
          cache-from: type=gha
          cache-to: type=gha,mode=max

      - name: Build nginx image
        uses: docker/build-push-action@v6
        with:
          context: ${{ runner.temp }}/docker-source/nginx
          file: ${{ runner.temp }}/docker-source/nginx/Dockerfile
          push: false
          load: true
          tags: authboiler-smoke-nginx:local
          cache-from: type=gha
          cache-to: type=gha,mode=max

      - name: Fetch synthetic database image
        run: |
          mkdir -p "$RUNNER_TEMP/docker-home" "$RUNNER_TEMP/docker-config"
          env -i PATH="$PATH" HOME="$RUNNER_TEMP/docker-home" docker --config "$RUNNER_TEMP/docker-config" pull mongo:7

      - name: Verify synthetic containers and HTTP nginx health
        run: env -i PATH="$PATH" node scripts/verify-docker.mjs
import { mkdir, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { MarkerError, removeFeatureLines, stripFeatureMarkers } from '../src/prune/markers.js';

const KNOWN = new Set(['totp', 'passkeys', 'magic-link', 'google']);

function strip(lines: string[], kept: string[], file = 'src/example.ts'): string {
  return stripFeatureMarkers(lines.join('\n'), file, new Set(kept), KNOWN).content;
}

const roots: string[] = [];

async function tree(files: Record<string, string>): Promise<string> {
  const root = await mkdtemp(join(tmpdir(), 'cna-markers-'));
  roots.push(root);
  for (const [path, content] of Object.entries(files)) {
    const target = join(root, path);
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, content, 'utf8');
  }
  return root;
}

afterEach(async () => {
  for (const root of roots.splice(0)) await rm(root, { recursive: true, force: true });
});

describe('stripFeatureMarkers', () => {
  it('drops a marked line for a feature that was not selected', () => {
    const source = [
      "import { one } from './one';",
      "import { two } from './two'; // feature:totp",
      'export const all = [one];',
    ];

    expect(strip(source, ['passkeys'])).toBe(
      ["import { one } from './one';", 'export const all = [one];'].join('\n'),
    );
  });

  it('takes the marker off a line that stays', () => {
    const source = ['  PasskeysModule, // feature:passkeys'];
    expect(strip(source, ['passkeys'])).toBe('  PasskeysModule,');
  });

  it('drops a line whose only content is the marker', () => {
    const source = ['const a = 1;', '// feature:totp', 'const b = 2;'];
    expect(strip(source, ['totp'])).toBe(['const a = 1;', 'const b = 2;'].join('\n'));
  });

  it('removes a whole block, marker lines included', () => {
    const source = [
      'function verify() {',
      '  // feature:passkeys:start',
      '  if (dto.passkeyResponse) {',
      '    return checkPasskey(dto);',
      '  }',
      '  // feature:passkeys:end',
      '  return checkCode(dto);',
      '}',
    ];

    expect(strip(source, ['totp'])).toBe(
      ['function verify() {', '  return checkCode(dto);', '}'].join('\n'),
    );
  });

  it('keeps a block body and drops only its marker lines when the feature stays', () => {
    const source = ['// feature:totp:start', 'const twoFactor = true;', '// feature:totp:end'];
    expect(strip(source, ['totp'])).toBe('const twoFactor = true;');
  });

  it('handles a block nested inside another block', () => {
    const source = [
      '// feature:totp:start',
      'const outer = 1;',
      '  // feature:passkeys:start',
      '  const inner = 2;',
      '  // feature:passkeys:end',
      'const after = 3;',
      '// feature:totp:end',
      'const tail = 4;',
    ];

    expect(strip(source, ['totp'])).toBe(
      ['const outer = 1;', 'const after = 3;', 'const tail = 4;'].join('\n'),
    );
    expect(strip(source, ['totp', 'passkeys'])).toBe(
      ['const outer = 1;', '  const inner = 2;', 'const after = 3;', 'const tail = 4;'].join('\n'),
    );
    expect(strip(source, ['google'])).toBe('const tail = 4;');
  });

  it('keeps a comma list when any of its ids is selected', () => {
    const source = ['const shared = true; // feature:totp,passkeys'];

    expect(strip(source, ['passkeys'])).toBe('const shared = true;');
    expect(strip(source, ['totp'])).toBe('const shared = true;');
    expect(strip(source, ['google'])).toBe('');
  });

  it('reads the JSX comment forms', () => {
    const source = [
      "import { Card } from '@/modules/passkeys'; // feature:passkeys",
      '<div>',
      '  {/* feature:totp:start */}',
      '  <TwoFactorCard />',
      '  {/* feature:totp:end */}',
      '  <PasskeysCard /> {/* feature:passkeys */}',
      '</div>',
    ];

    expect(strip(source, ['passkeys'], 'src/page.tsx')).toBe(
      ["import { Card } from '@/modules/passkeys';", '<div>', '  <PasskeysCard />', '</div>'].join(
        '\n',
      ),
    );
    expect(strip(source, ['totp'], 'src/page.tsx')).toBe(
      ['<div>', '  <TwoFactorCard />', '</div>'].join('\n'),
    );
  });

  it('leaves a file without markers byte for byte alone', () => {
    const content = 'const feature = "feature:not-a-marker";\n// a plain comment\n';
    expect(stripFeatureMarkers(content, 'src/a.ts', new Set(), KNOWN).content).toBe(content);
  });

  it('rejects an id the manifest does not list', () => {
    expect(() => strip(['const a = 1; // feature:passkey'], ['passkeys'])).toThrow(MarkerError);
    expect(() => strip(['const a = 1; // feature:passkey'], ['passkeys'])).toThrow(
      /src\/example.ts:1 marks feature "passkey"/,
    );
  });

  it('rejects a malformed marker', () => {
    for (const marker of ['Totp!', '', 'totp passkeys', 'totp,,passkeys']) {
      expect(() => strip([`const a = 1; // feature:${marker}`], ['totp'])).toThrow(
        /malformed feature marker/,
      );
    }
  });

  it('preserves CRLF line endings while stripping selected markers', () => {
    const source = 'const a = 1; // feature:totp\r\nconst b = 2;\r\n';
    expect(stripFeatureMarkers(source, 'src/a.ts', new Set(['totp']), KNOWN).content).toBe(
      'const a = 1;\r\nconst b = 2;\r\n',
    );
  });

  it('rejects a block that is never closed', () => {
    expect(() => strip(['// feature:totp:start', 'const a = 1;'], ['totp'])).toThrow(
      /opens totp and never closes it/,
    );
  });

  it('rejects an end that closes a different block', () => {
    const source = ['// feature:totp:start', 'const a = 1;', '// feature:passkeys:end'];
    expect(() => strip(source, ['totp'])).toThrow(/closes passkeys while totp is open/);
  });

  it('rejects a block marker sharing a line with code', () => {
    expect(() => strip(['const a = 1; // feature:totp:start'], ['totp'])).toThrow(
      /start marker on a line that also carries code/,
    );
  });

  it('handles every selection through three nested feature blocks', () => {
    const ids = ['totp', 'passkeys', 'magic-link'];
    const source = [
      '// feature:totp:start',
      'outer',
      '// feature:passkeys:start',
      'middle',
      '// feature:magic-link:start',
      'inner',
      '// feature:magic-link:end',
      '// feature:passkeys:end',
      'after',
      '// feature:totp:end',
      'tail',
    ];

    for (let mask = 0; mask < 8; mask += 1) {
      const kept = ids.filter((_, index) => (mask & (1 << index)) !== 0);
      const expected: string[] = [];
      if (kept.includes('totp')) {
        expected.push('outer');
        if (kept.includes('passkeys')) {
          expected.push('middle');
          if (kept.includes('magic-link')) expected.push('inner');
        }
        expected.push('after');
      }
      expected.push('tail');
      expect(strip(source, kept)).toBe(expected.join('\n'));
    }
  });

  it('rejects malformed nesting even inside a removed block', () => {
    expect(() => strip(['// feature:totp:end'], [])).toThrow(/never opened/);
    expect(() => strip(['// feature:totp:start', '// feature:missing:start'], [])).toThrow(
      /marks feature "missing"/,
    );
  });

  it('handles deeply nested blocks without recursive traversal', () => {
    const depth = 5000;
    const source = [
      ...Array<string>(depth).fill('// feature:totp:start'),
      'inside',
      ...Array<string>(depth).fill('// feature:totp:end'),
      'outside',
    ];
    expect(strip(source, ['totp'])).toBe('inside\noutside');
    expect(strip(source, [])).toBe('outside');
  });
});

describe('removeFeatureLines', () => {
  it('edits source files and leaves json and markdown alone', async () => {
    const root = await tree({
      'src/registry.ts': ['export const all = [', '  totp, // feature:totp', '];', ''].join('\n'),
      'docs/guide.md': '- totp // feature:totp\n',
      'config.json': '{ "note": "feature:totp" }\n',
      'src/plain.ts': 'export const one = 1;\n',
    });

    const result = await removeFeatureLines(root, ['passkeys'], [...KNOWN]);

    expect(result.editedFiles).toEqual(['src/registry.ts']);
    expect(result.removedLines).toBe(1);
    expect(await readFile(join(root, 'src/registry.ts'), 'utf8')).toBe(
      'export const all = [\n];\n',
    );
    expect(await readFile(join(root, 'docs/guide.md'), 'utf8')).toBe('- totp // feature:totp\n');
    expect(await readFile(join(root, 'config.json'), 'utf8')).toBe('{ "note": "feature:totp" }\n');
    expect(await readFile(join(root, 'src/plain.ts'), 'utf8')).toBe('export const one = 1;\n');
  });

  it('strips the markers of selected features so the output carries none', async () => {
    const root = await tree({
      'src/app.module.mjs': ['export const modules = [', '  Totp, // feature:totp', '];', ''].join(
        '\n',
      ),
    });

    await removeFeatureLines(root, ['totp'], [...KNOWN]);

    const content = await readFile(join(root, 'src/app.module.mjs'), 'utf8');
    expect(content).toBe('export const modules = [\n  Totp,\n];\n');
    expect(content).not.toContain('feature:');
  });

  it('names the file and line when a marker is wrong', async () => {
    const root = await tree({ 'src/bad.ts': 'const a = 1; // feature:nope\n' });
    await expect(removeFeatureLines(root, ['totp'], [...KNOWN])).rejects.toThrow(
      /src\/bad.ts:1 marks feature "nope"/,
    );
  });
});
import { readFile, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { stripEnvVars } from '../src/prune/env.js';
import { prune } from '../src/prune/index.js';
import { listFiles } from '../src/utils/fs.js';
import { createFixtureTree, FIXTURE_MANIFEST } from './fixture.js';

const roots: string[] = [];

async function fixture(): Promise<string> {
  const root = await createFixtureTree();
  roots.push(root);
  return root;
}

afterEach(async () => {
  for (const root of roots.splice(0)) await rm(root, { recursive: true, force: true });
});

describe('prune', () => {
  it('deletes only what the unselected features own', async () => {
    const root = await fixture();
    const result = await prune(root, FIXTURE_MANIFEST, ['email-password', 'alpha']);
    const files = await listFiles(root);

    expect(result.deletedFiles).toEqual([
      'docs/setup-beta.md',
      'src/strategies/beta-oauth.strategy.ts',
      'tooling/internal.md',
    ]);
    expect(files).toContain('src/strategies/alpha-oauth.strategy.ts');
    expect(files).toContain('src/strategies/alpha-oauth.strategy.spec.ts');
    expect(files).toContain('docs/setup-alpha.md');
    expect(files).toContain('docs/setup-smtp.md');
    expect(files).not.toContain('src/strategies/beta-oauth.strategy.ts');
    expect(files).not.toContain('tooling/internal.md');
    expect(result.dangling).toEqual([]);
  });

  it('strips the env lines of removed features and keeps shared ones', async () => {
    const root = await fixture();
    const result = await prune(root, FIXTURE_MANIFEST, ['email-password', 'alpha']);

    const backend = await readFile(join(root, 'backend/.env.example'), 'utf8');
    const docker = await readFile(join(root, '.env.docker.example'), 'utf8');

    expect(result.strippedEnvVars).toEqual(['OAUTH_BETA_CLIENT_ID']);
    expect(backend).not.toContain('OAUTH_BETA_CLIENT_ID');
    expect(backend).not.toContain('# Beta OAuth');
    expect(backend).toContain('# OAUTH_ALPHA_CLIENT_ID=alpha-id');
    expect(backend).toContain('SHARED_KEY=shared');
    expect(backend).toContain('SWAGGER_ENABLED=false');
    expect(docker).not.toContain('OAUTH_BETA_CLIENT_ID');
    expect(docker).toContain('NEXT_PUBLIC_API_URL=http://localhost:5000');
  });

  it('keeps a shared var when only one of its owners is removed', async () => {
    const root = await fixture();
    await prune(root, FIXTURE_MANIFEST, ['email-password']);
    const backend = await readFile(join(root, 'backend/.env.example'), 'utf8');

    expect(backend).toContain('SHARED_KEY=shared');
    expect(backend).not.toContain('OAUTH_ALPHA_CLIENT_ID');
  });

  it('records the enabled features in the backend env example', async () => {
    const root = await fixture();
    await prune(root, FIXTURE_MANIFEST, ['email-password', 'alpha']);
    const backend = await readFile(join(root, 'backend/.env.example'), 'utf8');

    expect(backend).toContain('AUTH_FEATURES=email-password,alpha');
    expect(backend.match(/AUTH_FEATURES=/g)).toHaveLength(1);
  });

  it('removes doc links from lists and tables, and leaves the rest', async () => {
    const root = await fixture();
    const result = await prune(root, FIXTURE_MANIFEST, ['email-password', 'alpha']);

    const docsIndex = await readFile(join(root, 'docs/README.md'), 'utf8');
    const readme = await readFile(join(root, 'README.md'), 'utf8');

    expect(result.removedDocLines).toBe(2);
    expect(docsIndex).not.toContain('setup-beta.md');
    expect(docsIndex).toContain('setup-alpha.md');
    expect(readme).not.toContain('docs/setup-beta.md');
    expect(readme).toContain('| Guide | Description |');
  });

  it('reports imports left pointing at deleted files', async () => {
    const root = await fixture();
    const result = await prune(root, FIXTURE_MANIFEST, ['email-password', 'beta']);

    expect(result.dangling).toHaveLength(1);
    expect(result.dangling[0]).toMatchObject({
      file: 'src/auth.module.ts',
      line: 1,
      specifier: './strategies/alpha-oauth.strategy',
    });
  });

  it('removes planned features that never made it into the prompt', async () => {
    const root = await fixture();
    const result = await prune(root, FIXTURE_MANIFEST, ['email-password', 'alpha', 'beta']);
    expect(result.removed).toEqual(['gamma']);
  });
});

describe('stripEnvVars', () => {
  it('drops a commented assignment and the comment above it', () => {
    const content = ['# Beta OAuth (optional)', '# OAUTH_BETA_CLIENT_ID=id', ''].join('\n');
    const result = stripEnvVars(content, new Map([['OAUTH_BETA_CLIENT_ID', ['Beta', 'beta']]]));

    expect(result.content.trim()).toBe('');
    expect(result.stripped).toEqual(['OAUTH_BETA_CLIENT_ID']);
  });

  it('keeps a comment that does not name the feature', () => {
    const content = ['# Rate limiting', 'OAUTH_BETA_CLIENT_ID=id', 'THROTTLE_TTL=60'].join('\n');
    const result = stripEnvVars(content, new Map([['OAUTH_BETA_CLIENT_ID', ['Beta', 'beta']]]));

    expect(result.content).toContain('# Rate limiting');
    expect(result.content).toContain('THROTTLE_TTL=60');
  });

  it('leaves a file with no removals alone apart from the trailing newline', () => {
    const content = 'A=1\nB=2\n';
    expect(stripEnvVars(content, new Map()).content).toBe(content);
  });
});

