/** Directories the pruner never walks into. */
export const SKIPPED_DIRS = new Set(['node_modules', '.git', 'dist', '.next', 'out', 'coverage']);

export const DEFAULT_COMMIT_MESSAGE = 'chore: scaffold from create-nest-next-auth';

