import { spawn } from 'node:child_process';

export interface RunResult {
  code: number;
  stdout: string;
  stderr: string;
}

/** Runs a command without a shell and collects its output. Never throws. */
export function run(command: string, args: string[], cwd: string): Promise<RunResult> {
  return new Promise((resolve) => {
    const child = spawn(command, args, { cwd, stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '';
    let stderr = '';

    child.stdout.on('data', (chunk: Buffer) => {
      stdout += chunk.toString();
    });
    child.stderr.on('data', (chunk: Buffer) => {
      stderr += chunk.toString();
    });
    child.on('error', (error: Error) => {
      resolve({ code: 127, stdout, stderr: error.message });
    });
    child.on('close', (code: number | null) => {
      resolve({ code: code ?? 1, stdout, stderr });
    });
  });
}

export function lastLines(text: string, count: number): string {
  return text.trimEnd().split('\n').slice(-count).join('\n');
}
import { readdir, rm, rmdir } from 'node:fs/promises';
import { dirname, join, posix, relative, sep } from 'node:path';
import { SKIPPED_DIRS } from '../constants/index.js';

/** Lists every file under `root` as a posix path relative to `root`. */
export async function listFiles(root: string): Promise<string[]> {
  const found: string[] = [];

  async function walk(directory: string): Promise<void> {
    const entries = await readdir(directory, { withFileTypes: true });
    for (const entry of entries) {
      const full = join(directory, entry.name);
      if (entry.isDirectory()) {
        if (SKIPPED_DIRS.has(entry.name)) continue;
        await walk(full);
        continue;
      }
      if (entry.isFile()) found.push(toPosix(relative(root, full)));
    }
  }

  await walk(root);
  return found.sort();
}

export function toPosix(path: string): string {
  return path.split(sep).join(posix.sep);
}

/** Removes a file and any directories it leaves empty, stopping at `root`. */
export async function removeFile(root: string, relativePath: string): Promise<void> {
  const target = join(root, relativePath);
  await rm(target, { force: true });

  let directory = dirname(target);
  while (directory.startsWith(root) && directory !== root) {
    try {
      await rmdir(directory);
    } catch {
      return;
    }
    directory = dirname(directory);
  }
}
const SPECIAL_CHARS = /[.+^${}()|[\]\\]/g;

/**
 * Translates a posix-style glob into a RegExp. Supports `?`, `*` (one segment)
 * and `**` (any number of segments). Enough for manifest paths; no braces or
 * character classes.
 */
export function globToRegExp(glob: string): RegExp {
  let pattern = '';
  let index = 0;

  while (index < glob.length) {
    const char = glob[index];

    if (char === '*') {
      const isDoubleStar = glob[index + 1] === '*';
      if (isDoubleStar) {
        const skipsSlash = glob[index + 2] === '/';
        pattern += skipsSlash ? '(?:.*\\/)?' : '.*';
        index += skipsSlash ? 3 : 2;
        continue;
      }
      pattern += '[^/]*';
      index += 1;
      continue;
    }

    if (char === '?') {
      pattern += '[^/]';
      index += 1;
      continue;
    }

    pattern += char.replace(SPECIAL_CHARS, '\\$&');
    index += 1;
  }

  return new RegExp(`^${pattern}$`);
}

export function matchesGlob(path: string, glob: string): boolean {
  return globToRegExp(glob).test(path);
}

export function matchesAnyGlob(path: string, globs: string[]): boolean {
  return globs.some((glob) => matchesGlob(path, glob));
}
const WINDOWS_RESERVED = new Set([
  'con',
  'prn',
  'aux',
  'nul',
  ...Array.from({ length: 9 }, (_, index) => `com${index + 1}`),
  ...Array.from({ length: 9 }, (_, index) => `lpt${index + 1}`),
]);

const ILLEGAL_CHARS = new Set(['<', '>', ':', '"', '|', '?', '*', '/', '\\', ' ']);

const LOWEST_PRINTABLE_CODE = 32;

const MAX_LENGTH = 214;

export interface NameCheck {
  valid: boolean;
  message?: string;
}

function hasIllegalCharacter(name: string): boolean {
  for (const character of name) {
    if (ILLEGAL_CHARS.has(character)) return true;
    if ((character.codePointAt(0) ?? 0) < LOWEST_PRINTABLE_CODE) return true;
  }
  return false;
}

/** Checks the last path segment of the target, which becomes the directory name. */
export function validateProjectName(name: string): NameCheck {
  if (name.length === 0) return { valid: false, message: 'Enter a project name.' };
  if (name.length > MAX_LENGTH) {
    return { valid: false, message: `Use ${MAX_LENGTH} characters or fewer.` };
  }
  if (name === '.' || name === '..') {
    return { valid: false, message: 'Enter a name, not a relative path.' };
  }
  if (hasIllegalCharacter(name)) {
    return { valid: false, message: 'Use a name without spaces, slashes or : * ? " < > | .' };
  }
  if (name.trim() !== name || name.endsWith('.')) {
    return { valid: false, message: 'Remove the leading or trailing space or dot.' };
  }
  if (name.startsWith('.')) {
    return { valid: false, message: 'Names starting with a dot are hidden directories.' };
  }
  if (WINDOWS_RESERVED.has(name.toLowerCase())) {
    return { valid: false, message: `${name} is a reserved name on Windows.` };
  }
  return { valid: true };
}

/** Turns a directory name into something npm accepts as a package name. */
export function toPackageName(name: string): string {
  const cleaned = name
    .toLowerCase()
    .replace(/[^a-z0-9-._~]/g, '-')
    .replace(/^[-._]+/, '')
    .replace(/-{2,}/g, '-')
    .slice(0, MAX_LENGTH);
  return cleaned.length > 0 ? cleaned : 'app';
}
import { Command } from 'commander';
import { CLI_NAME } from '../constants/index.js';
import type { CliOptions } from '../types.js';

interface RawOptions {
  yes?: boolean;
  features?: string;
  install: boolean;
  git: boolean;
}

export function splitFeatureList(value: string): string[] {
  return value
    .split(',')
    .map((entry) => entry.trim().toLowerCase())
    .filter((entry) => entry.length > 0);
}

export function buildProgram(version: string): Command {
  return new Command()
    .name(CLI_NAME)
    .description('Scaffold a NestJS and Next.js authentication project.')
    .version(version, '-v, --version')
    .argument('[directory]', 'directory to create, defaults to a prompt')
    .option('-y, --yes', 'accept the defaults and skip the prompts')
    .option('--features <list>', 'comma separated feature ids, skips the feature prompt')
    .option('--no-install', 'skip npm install')
    .option('--no-git', 'skip git init and the first commit')
    .allowExcessArguments(false)
    .exitOverride();
}

/** Parses user arguments. Throws CommanderError on bad input, --help and --version. */
export function parseCliOptions(argv: string[], version = '0.0.0'): CliOptions {
  const program = buildProgram(version);
  program.parse(argv, { from: 'user' });

  const raw = program.opts<RawOptions>();
  return {
    directory: program.args[0],
    yes: raw.yes === true,
    features: raw.features === undefined ? undefined : splitFeatureList(raw.features),
    install: raw.install,
    git: raw.git,
  };
}
