    85	export function command(executable, args, { cwd, env, timeout = 30_000, signal } = {}) {
    86	  return new Promise((resolveCommand, reject) => {
    87	    const child = spawn(executable, args, {
    88	      cwd,
    89	      env,
    90	      stdio: ['ignore', 'pipe', 'pipe'],
    91	      detached: process.platform !== 'win32',
    92	    });
    93	    let stdout = '';
    94	    let bytes = 0;
    95	    let failure;
    96	    let killTimer;
    97	    function kill(processSignal) {
    98	      try {
    99	        if (process.platform === 'win32') child.kill(processSignal);
   100	        else process.kill(-child.pid, processSignal);
   101	      } catch (error) {
   102	        if (error.code !== 'ESRCH') failure ??= error;
   103	      }
   104	    }
   105	    function stop(reason) {
   106	      if (failure) return;
   107	      failure = new Error(reason);
   108	      kill('SIGTERM');
   109	      killTimer = setTimeout(() => kill('SIGKILL'), 2000);
   110	    }
   111	    const timer = setTimeout(() => stop('command timed out'), timeout);
   112	    const abort = () => stop('cancelled');
   113	    signal?.addEventListener('abort', abort, { once: true });
   114	    if (signal?.aborted) abort();
   115	    child.stdout.on('data', (chunk) => {
   116	      bytes += chunk.length;
   117	      if (bytes > MAX_OUTPUT) stop('command output limit exceeded');
   118	      else stdout += chunk.toString();
   119	    });
   120	    // Runtime logs can contain configuration. Drain stderr without retaining it.
   121	    child.stderr.resume();
   122	    child.on('error', (error) => {
   123	      failure = new Error(`cannot start ${executable}: ${error.code}`);
   124	    });
   125	    child.on('close', (code) => {
   126	      clearTimeout(timer);
   127	      clearTimeout(killTimer);
   128	      signal?.removeEventListener('abort', abort);
   129	      if (failure) reject(failure);
   130	      else if (code !== 0) reject(new Error(`${executable} ${args[0]} exited ${code}`));
   131	      else resolveCommand(stdout.trim());
   132	    });
   133	  });
   134	}
